def _project(
    record: Mapping[str, Any],
    fields: Mapping[str, str],
) -> dict[str, Any]:
    """Render the checked field names with the values found in *record*."""
    projected: dict[str, Any] = {}
    for name, source_key in fields.items():
        value = _field_value(record, source_key)
        projected[name] = None if value is MISSING else value
    return projected


def _identity(record: Mapping[str, Any], keys: Sequence[str]) -> dict[str, Any]:
    return {key: _canonical(record.get(key)) for key in keys if key in record}


def _expected_fields(
    spec: Mapping[str, str],
    fields: Mapping[str, str],
) -> dict[str, Any]:
    lookup = {name: source_key for name, source_key in fields.items()}
    return {name: spec[source_key] for name, source_key in lookup.items() if source_key in spec}


