    @classmethod
    def _session_start(cls, sessions: Sequence[Mapping[str, Any]]) -> str:
        stamps = [
            str(session.get("createdAt") or session.get("created_at") or "").strip()
            for session in sessions
            if str(session.get("userId") or "") in {"", "usr_rider_primary"}
        ]
        usable = [stamp for stamp in stamps if datetime_value(stamp) is not None]
        if not usable:
            return ""
        return max(usable, key=lambda stamp: datetime_value(stamp) or datetime_value("1970-01-01"))

    @classmethod
    def _after_boundary(cls, record: Mapping[str, Any], boundary: str) -> bool:
        stamp = record.get("createdAt") or record.get("created_at")
        return is_after(stamp, boundary)

    @staticmethod
    def _record_id(record: Mapping[str, Any]) -> str:
        return str(record.get("id") or "")

    @classmethod
    def _check_account(cls, walk: _Walk, users: Sequence[Mapping[str, Any]]) -> None:
        expected = {"id": "usr_rider_primary", "email": RIDER_EMAIL, "role": RIDER_ROLE}
        matches = [user for user in users if _record_matches(user, expected)]
        passed = len(matches) == 1
        actual = {
            "match_count": len(matches),
            "record": _project(matches[0], ACCOUNT_FIELDS) if matches else None,
        }
        walk.record(
            "authenticated_primary_rider",
            passed=passed,
            expected=expected,
            actual=actual,
            failure_reason="the authenticated OpenDriver rider account is not present exactly once",
        )

    @classmethod
    def _single_ride(
        cls,
        walk: _Walk,
        rides: Sequence[Mapping[str, Any]],
        spec: Mapping[str, Any],
        label: str,
    ) -> Mapping[str, Any] | None:
        matches = [ride for ride in rides if _record_matches(ride, spec)]
        chosen = matches[0] if len(matches) == 1 else None
        expected = _expected_fields(spec, RIDE_FIELDS)
        actual = {
            "match_count": len(matches),
            "ride_id": cls._record_id(chosen) if chosen else None,
            "matches": [_project(ride, RIDE_FIELDS) for ride in matches[:3]],
            "candidates": [_identity(ride, _RIDE_IDENTITY) for ride in rides[:3]] if not matches else [],
        }
        walk.record(
            label,
            passed=len(matches) == 1,
            expected=expected,
            actual=actual,
            failure_reason=(
                f"{label} must match exactly one cancelled Green ride in the rides collection"
            ),
        )
        return chosen

    @classmethod
    def _check_current_session_rides(
        cls,
        walk: _Walk,
        rides: Sequence[Mapping[str, Any]],
        boundary: str,
        seed_time: str,
        session_start: str,
    ) -> None:
        current = [ride for ride in rides if cls._after_boundary(ride, boundary)]
        statuses = [str(ride.get("status") or "") for ride in current]
        all_cancelled = bool(current) and all(status == "cancelled" for status in statuses)
        passed = len(current) == 2 and all_cancelled
        walk.record(
            "exactly_two_current_session_rides_cancelled",
            passed=passed,
            expected={
                "ride_count": 2,
                "statuses": ["cancelled", "cancelled"],
                "created_after_session_start": True,
            },
            actual={
                "ride_count": len(current),
                "record_ids": [ride.get("id") for ride in current],
                "record_statuses": statuses,
                "record_created_at": [ride.get("createdAt") for ride in current],
                "session_started_at": session_start,
                "seed_time": seed_time,
                "boundary": boundary,
            },
            failure_reason=(
                "the rides collection must hold exactly two records created for this session, "
                "both cancelled"
            ),
        )

    @classmethod
    def _check_no_active_ride(cls, walk: _Walk, rides: Sequence[Mapping[str, Any]]) -> None:
        active = [
            ride for ride in rides if str(ride.get("status") or "").strip() in ACTIVE_RIDE_STATUSES
        ]
        passed = not active
        walk.record(
            "no_active_ride_remains",
            passed=passed,
            expected={"active_ride_count": 0, "active_statuses": sorted(ACTIVE_RIDE_STATUSES)},
            actual={
                "active_ride_count": len(active),
                "record_ids": [ride.get("id") for ride in active],
                "record_statuses": [ride.get("status") for ride in active],
            },
            failure_reason="an active ride is still present in the rides collection",
        )

    @classmethod
    def _check_refund_targets(cls, walk: _Walk, rides: Sequence[Mapping[str, Any]]) -> None:
        for target in REFUND_TARGETS:
            expected = dict(target)
            matches = [ride for ride in rides if _record_matches(ride, expected)]
            chosen = matches[0] if len(matches) == 1 else None
            actual = {
                "match_count": len(matches),
                "ride_id": cls._record_id(chosen) if chosen else None,
                "pickup": _field_value(chosen, "pickup") if chosen else None,
                "destination": _field_value(chosen, "destination") if chosen else None,
                "matches": [
                    {
                        "ride_id": ride.get("id"),
                        "pickup": _field_value(ride, "pickup"),
                        "destination": _field_value(ride, "destination"),
                    }
                    for ride in matches[:3]
                ],
            }
            walk.record(
                f"refund_target_{target['ride_id']}",
                passed=len(matches) == 1,
                expected=expected,
                actual=actual,
                failure_reason=(
                    f"the seeded history ride {target['ride_id']} does not carry the named "
                    "pickup and destination in the rides collection"
                ),
            )

    @classmethod
    def _check_refunds(
        cls,
        walk: _Walk,
        refunds: Sequence[Mapping[str, Any]],
        boundary: str,
    ) -> None:
        current = [refund for refund in refunds if cls._after_boundary(refund, boundary)]
        matched_ids: set[str] = set()
        positions: dict[str, int] = {}
        for target in REFUND_TARGETS:
            wanted = {"ride_id": target["ride_id"], **REFUND_EXPECTATION}
            for index, refund in enumerate(current):
                if index in matched_ids:
                    continue
                if _record_matches(refund, wanted):
                    matched_ids.add(index)
                    positions[target["ride_id"]] = index
                    break
        passed = len(current) == 2 and len(positions) == len(REFUND_TARGETS)
        walk.record(
            "exactly_two_current_session_fare_review_refunds",
            passed=passed,
            expected={
                "refund_count": 2,
                "refunds": [
                    {**REFUND_EXPECTATION, "ride_id": target["ride_id"]}
                    for target in REFUND_TARGETS
                ],
                "created_after_session_start": True,
            },
            actual={
                "refund_count": len(current),
                "record_ids": [refund.get("id") for refund in current],
                "refunds": [_project(refund, REFUND_FIELDS) for refund in current],
                "matched_ride_ids": sorted(positions),
                "boundary": boundary,
            },
            failure_reason=(
                "the refunds collection must hold exactly two requested Fare review refunds for "
                "this session, one for each named history ride"
            ),
        )

    @classmethod
    def _check_ticket(
        cls,
        walk: _Walk,
        tickets: Sequence[Mapping[str, Any]],
        boundary: str,
    ) -> None:
        current = [ticket for ticket in tickets if cls._after_boundary(ticket, boundary)]
        qualified: list[Mapping[str, Any]] = []
        for ticket in current:
            if not _record_matches(ticket, TICKET_CREATE_EXPECTATION):
                continue
            replies = ticket.get("replies")
            reply_list = replies if isinstance(replies, list) else []
            if any(
                isinstance(reply, Mapping) and _text(reply.get("message")) == TICKET_REPLY_MESSAGE
                for reply in reply_list
            ):
                qualified.append(ticket)
        passed = len(qualified) == 1
        walk.record(
            "one_current_open_blue_umbrella_ticket_with_rear_seat_reply",
            passed=passed,
            expected={
                **TICKET_CREATE_EXPECTATION,
                "reply_message": TICKET_REPLY_MESSAGE,
            },
            actual={
                "match_count": len(qualified),
                "record_ids": [ticket.get("id") for ticket in qualified],
                "candidates": [
                    {
                        **_project(ticket, TICKET_FIELDS),
                        "replies": [
                            {
                                "id": reply.get("id"),
                                "message": reply.get("message"),
                            }
                            for reply in (ticket.get("replies") or [])
                            if isinstance(reply, Mapping)
                        ],
                    }
                    for ticket in current[:3]
                ],
                "boundary": boundary,
            },
            failure_reason=(
                "one open Blue umbrella support ticket must carry the rider's Rear seat reply"
            ),
        )

    # -- entry point ---------------------------------------------------
    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        binding = self.binding_errors(params)
        if binding:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="OpenDriver evaluator binding mismatch: " + "; ".join(binding),
                metadata={
                    "read_only": True,
                    "task_id": TASK_ID,
                    "evaluator_id": EVALUATOR_ID,
                    "checks": [],
                    "failed_checks": ["binding"],
                },
            )

        udid = self.declared_udid(params)
        if not udid:
            return EvalResult(
                status=EvalStatus.ERROR,
                message="the task parameters declare no simulator UDID; no default device is assumed",
                metadata={
                    "read_only": True,
                    "task_id": TASK_ID,
                    "evaluator_id": EVALUATOR_ID,
                    "checks": [],
                    "failed_checks": ["simulator_binding"],
                },
            )

        try:
            store = OpenDriverStore.from_params(params, context=context, bundle_id=BUNDLE_ID)
            document = store.read_state()
        except OpenDriverStoreError as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"OpenDriver state could not be read: {type(exc).__name__}: {exc}",
                metadata={
                    "read_only": True,
                    "task_id": TASK_ID,
                    "evaluator_id": EVALUATOR_ID,
                    "checks": [],
                    "failed_checks": ["state_read"],
                    "simulator_udid": udid,
                },
            )
        except Exception as exc:  # noqa: BLE001
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"OpenDriver evaluator error: {type(exc).__name__}: {exc}",
                metadata={
                    "read_only": True,
                    "task_id": TASK_ID,
                    "evaluator_id": EVALUATOR_ID,
                    "checks": [],
                    "failed_checks": ["evaluator_error"],
                    "simulator_udid": udid,
                },
            )

        result = self.evaluate_state(document, bundle_id=BUNDLE_ID)
        result.metadata["simulator_udid"] = udid
        result.metadata["db_path"] = str(store.db_path)
        return result


